.weblayer { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: [[ {name: 'Background', tooltip: 'Background', category: 'Branding', orderIndex: '1001', isJsonParam: true} : color | #ffffff ]]; font-family: {{ fontFamily }}; max-width: [[ {name: 'CardWidth', tooltip: 'CardWidth', category: 'Layout', orderIndex: '2000', isJsonParam: true} : string | 420px ]]; }
